validation_logic.code:
// Validate opportunity number format
function validateOpportunityNumber(oppNumber) {
  // Must be exactly 18 characters
  if (oppNumber.length !== 18) {
    return { valid: false, error: "Must be exactly 18 characters" };
  }

  // Must be alphanumeric only
  if (!/^[A-Za-z0-9]+$/.test(oppNumber)) {
    return { valid: false, error: "Must contain only letters and numbers" };
  }

  return { valid: true };
}

windows_powershell.command:
# PowerShell command for Windows
$opportunityNumber = "OPPORTUNITY_NUMBER_PLACEHOLDER"
$user = if ($env:USERNAME) { $env:USERNAME } else { "unknown" }
$timestamp = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
$token = $env:GHE_TOKEN
$repo = if ($env:GITHUB_REPOSITORY) { $env:GITHUB_REPOSITORY } else { "N/A" }

if (-not $token) {
    Write-Error "GHE_TOKEN environment variable not set. Please set it with your IBM GitHub Enterprise Personal Access Token."
    exit 1
}

# Determine labels based on opportunity number
$labels = @("opportunity-tracking")
if ($opportunityNumber -eq "000000000000000000") {
    $labels += "education-testing"
}

$body = @{
    title = "Opportunity: $opportunityNumber"
    body = "**Submitted by:** $user`n**Opportunity Number:** $opportunityNumber`n**Repository:** $repo`n**Timestamp:** $timestamp"
    labels = $labels
} | ConvertTo-Json -Compress

try {
    $response = Invoke-RestMethod -Uri "https://github.ibm.com/api/v3/repos/WW-CE/seller-bobathon-builder/issues" `
        -Method Post `
        -Headers @{
            "Authorization" = "token $token"
            "Accept" = "application/vnd.github.v3+json"
            "User-Agent" = "Bobathon-Builder"
        } `
        -Body $body `
        -ContentType "application/json"

    Write-Host "✓ Opportunity $opportunityNumber submitted successfully"
    Write-Host "Issue URL: $($response.html_url)"
} catch {
    Write-Error "Failed to submit opportunity: $_"
    exit 1
}
